// Kits ativos
const kitsRows = $('Ler Kits').all().map(i => i.json);
const kits = kitsRows
  .filter(k => String(k.ativo).toUpperCase() === 'SIM')
  .map(k => ({
    id: String(k.id),
    nome: k.nome || '',
    tema: k.tema || '',
    descricao: k.descricao || '',
    preco_locacao: Number(k.preco_locacao) || 0,
    imagem_url: k.imagem_url || '',
    itens: String(k.itens || '').split('|').map(s => s.trim()).filter(Boolean)
  }));

// Datas indisponíveis = reservas ativas + bloqueios manuais
const STATUS_OCUPA = ['AGUARDANDO_PAGAMENTO', 'PAGO', 'CONCLUIDO'];
const datasReservas = $('Ler Reservas').all().map(i => i.json)
  .filter(r => STATUS_OCUPA.includes(String(r.status || '').toUpperCase()))
  .map(r => String(r.data_evento).slice(0, 10));
const datasBloqueios = $('Ler Bloqueios').all().map(i => i.json)
  .map(b => String(b.data).slice(0, 10))
  .filter(Boolean);

const indisponiveis = Array.from(new Set([...datasReservas, ...datasBloqueios])).sort();

const antecedencia = Number($env.FESTAS_ANTECEDENCIA_MIN_DIAS || 2);

return [{ json: {
  ok: true,
  kits,
  datas_indisponiveis: indisponiveis,
  taxas: {
    montagem: Number($env.FESTAS_TAXA_MONTAGEM) || 0,
    entrega_base: Number($env.FESTAS_TAXA_ENTREGA_BASE) || 0,
    entrega_km: Number($env.FESTAS_TAXA_ENTREGA_KM) || 0
  },
  antecedencia_min_dias: antecedencia,
  metodos_pagamento: ['pix', 'mercadopago']
} }];
